  return { ...p, phase: Number(p.phase), start_week: sw, end_week: ew,
    start_date: addDays(CONFIG.PROJECT_WEEK1_START, 7 * (sw - 1)),
    end_date: addDays(CONFIG.PROJECT_WEEK1_START, 7 * ew - 1) };
});
