const factsBlock = [
  `FACTS (computed by code for reporting date ${RD}; authoritative, do not recount)`,
  `- Task counts: Done ${counts.Done}, In Progress ${counts['In Progress']}, To Do ${counts['To Do']}, Blocked ${counts.Blocked}, Total ${counts.Total}`,
  `- Overall health: ${health}. Reason: ${healthReason}`,
  `- Current phase: ${currentPhase ? `Phase ${currentPhase.phase} ${currentPhase.phase_name} (weeks ${currentPhase.start_week}-${currentPhase.end_week}, ${currentPhase.start_date} to ${currentPhase.end_date})` : 'outside timeline'}`,
  `- Blocked tasks:\n${list(blocked)}`,
  `- Overdue tasks (not Done, due before ${RD}):\n${list(overdue)}`,
  `- Due soon (not Done, due ${RD} to ${addDays(RD, CONFIG.AT_RISK_WINDOW_DAYS)}):\n${list(dueSoon)}`,
  `- Upcoming milestones (phase-end deliverables due ${RD} to ${windowEnd}):\n` +
    (upcomingMilestones.length ? upcomingMilestones.map(m => `- Phase ${m.phase} ${m.phase_name}: ${m.milestones} (due ${m.due}, end of week ${m.end_week})`).join('\n') : '- none in window'),
  `- Next milestone after the window: ${nextAfterWindow ? `Phase ${nextAfterWindow.phase} ${nextAfterWindow.phase_name}: ${nextAfterWindow.milestones_deliverables} (due ${nextAfterWindow.end_date}, end of week ${nextAfterWindow.end_week})` : 'none'}`,
  `- Sprints on the board: ${sprintNames.join(', ')} (no other sprints exist). Task IDs: T001-T025 only.`,
].join('\n');

const sprintBlock = sprintNames.map(s => {
  const b = bySprint[s];
  // Sprint-scoped facts, so a sprint report never has to borrow the project-wide lists.
  const open = b.tasks.filter(t => t.status !== 'Done');
  const ids = arr => arr.length ? arr.map(t => t.id).join(', ') : 'none';
  const sOverdue = open.filter(t => t.due < RD), sBlocked = open.filter(t => t.status === 'Blocked');
  const sDueSoon = open.filter(t => t.due >= RD && daysBetween(RD, t.due) <= CONFIG.AT_RISK_WINDOW_DAYS);
  const sHealth = sOverdue.length || sBlocked.length ? 'Amber' : 'Green';
  return `### ${s} (Done ${b.counts.Done}, In Progress ${b.counts['In Progress']}, To Do ${b.counts['To Do']}, Blocked ${b.counts.Blocked})\n` +
    `Sprint facts: health ${sHealth} | blocked in this sprint: ${ids(sBlocked)} | overdue in this sprint: ${ids(sOverdue)} | due soon in this sprint: ${ids(sDueSoon)}\n` +
    b.tasks.map(t => `- ${t.id} ${t.name} | ${t.status} | owner ${t.owner} | due ${t.due}${t.status !== 'Done' && t.due < RD ? ' | OVERDUE' : ''}`).join('\n');
}).join('\n\n');

const kb = {
  planner: `## Source: project_description.txt\n${DESCRIPTION}\n\n## Source: project_timeline.csv (dates computed from week 1 = ${CONFIG.PROJECT_WEEK1_START}; 24 weeks total)\n${timelineTable}`,
  risk: `## Source: project_description.txt\n${DESCRIPTION}\n\n## Source: project_risks.csv (risk register)\n` +
    mdTable(['ID', 'Category', 'Risk', 'Impact', 'Mitigation'], risks.map(r => [r.risk_id, r.category, r.risk_challenge, r.impact, r.mitigation_strategy])) +
    `\n\n## Current Evidence (computed from the task board on ${RD}; rank 1 = most urgent)\n` +
    mdTable(['Rank', 'Risk ID', 'Category', 'Live signal'], riskEvidence.map(r => [r.rank, r.risk_id, r.category, r.evidence])) +
    `\nRanking rule: linked task Blocked (4) > Overdue (3) > In Progress and due within 7 days (2) > Not started and due within 14 days (1) > none (0); ties keep register order.`,
  status: `${factsBlock}\n\n## Per-sprint view\n${sprintBlock}\n\n## Source: sample_task_board.csv\n${boardTable}\n\n## Source: project_timeline.csv (phase dates)\n${timelineTable}`,
  update: `## Project\nAI Adoption Project for ABCDE Ltd. Stated goals: reduce delivery delays by 15%, lower operational costs by 10%, improve service responsiveness.\n\n${factsBlock}\n\n## Per-sprint view (use ONLY the requested sprint)\n${sprintBlock}`,
};

// 32 hex chars: an OpenTelemetry trace id, which Langfuse uses as its trace id.
const rid = () => Array.from({ length: 32 }, () => (Math.random() * 16 | 0).toString(16)).join('');

return {
  json: {
    ...$json,
    trace_id: $json.trace_id || rid(),
    config: { model: 'gpt-4o-mini', temperature: 0.2, router_temperature: 0, max_tokens: 1500,
      price_per_1m_input_usd: 0.15, price_per_1m_output_usd: 0.60,
      langfuse_host: 'https://us.cloud.langfuse.com', ...CONFIG },
    facts: { reporting_date: RD, counts, health, health_reason: healthReason, overdue, due_soon: dueSoon, blocked,
      current_phase: currentPhase && { phase: currentPhase.phase, name: currentPhase.phase_name },
      upcoming_milestones: upcomingMilestones,
      next_milestone_after_window: nextAfterWindow && { phase: nextAfterWindow.phase, name: nextAfterWindow.phase_name, due: nextAfterWindow.end_date, milestones: nextAfterWindow.milestones_deliverables },
      risk_ranking: riskEvidence.map(r => ({ rank: r.rank, risk_id: r.risk_id, evidence: r.evidence })),
      sprint_counts: Object.fromEntries(sprintNames.map(s => [s, bySprint[s].counts])) },
    data_ids: { tasks: tasks.map(t => t.task_id), risks: risks.map(r => r.risk_id), sprints: sprintNames, phases: phases.length },
    kb,
  },
};

// ============================================================================
// Mira | Node: "Parse Route"   (Code node, Run Once for Each Item)
// Reads the Router agent's JSON answer and guarantees a valid route.
// Any malformed router output falls back to "clarify" (never guess a specialist).
// ============================================================================
const ctx = $('Prompt Registry').item.json;
const raw = $json.choices?.[0]?.message?.content || '';
const DEFAULT_REPLY = "I'm not sure what you need yet. For the ABCDE Ltd. AI Adoption Project I can create a project plan, a risk assessment, a weekly status report, or a stakeholder update email. Which would you like?";
let parsed;
try { parsed = JSON.parse(raw); }
catch (e) { parsed = { route: 'clarify', reason: 'Router output was not valid JSON', reply: DEFAULT_REPLY }; }

const ALLOWED = ['plan', 'risk', 'status', 'update', 'clarify'];
let route = String(parsed.route || '').toLowerCase().trim();
if (!ALLOWED.includes(route)) route = 'clarify';
const reply = route === 'clarify' ? (String(parsed.reply || '').trim() || DEFAULT_REPLY) : '';

return {
  json: {
    ...ctx,
    route,
    router_reason: String(parsed.reason || ''),
    router_reply: reply,
    router_usage: $json.usage || null,
    router_model: $json.model || ctx.config.model,
    router_raw: raw,
    router_done_at: new Date().toISOString(),
  },
};

// ============================================================================
// Mira | Node: "Response Formatter"   (Code node, Run Once for Each Item)
// Receives either a specialist's OpenAI response or the clarify branch, and
// produces one standard result object for every route.
// ============================================================================
const ctx = $('Parse Route').item.json;
const fromLLM = Array.isArray($json.choices);
const AGENTS = { plan: 'Planner Agent', risk: 'Risk Assessor Agent', status: 'Status Reporter Agent',
  update: 'Stakeholder Update Agent', clarify: 'Router (clarifying questions)' };

let output = fromLLM ? String($json.choices[0]?.message?.content || '').trim() : ctx.router_reply;
if (!output) output = 'Mira could not produce an answer. Please rephrase your request.';

// FR-6/FR-7: every specialist answer carries sources + the PM review note.
const SOURCES = { plan: 'project_description.txt, project_timeline.csv', risk: 'project_description.txt, project_risks.csv, sample_task_board.csv (evidence)',
  status: 'sample_task_board.csv, project_timeline.csv', update: 'sample_task_board.csv, project_description.txt' };
let footer_added = false; // true = the agent forgot the footer and the formatter added it (format-compliance metric)
if (fromLLM) {
  if (!/_?Sources:/i.test(output)) { output += `\n\n_Sources: ${SOURCES[ctx.route]}_`; footer_added = true; }
  if (!/Draft for PM review/i.test(output)) { output += `\n_Draft for PM review — verify before sharing._`; footer_added = true; }
}

const usage = fromLLM ? ($json.usage || null) : null;
const { kb, prompts, global_prompt, ...lean } = ctx; // keep the item small after this point
return {
  json: {
    ...lean,
    agent: AGENTS[ctx.route],
    output,
    footer_added,
    specialist_usage: usage,
    specialist_model: fromLLM ? ($json.model || ctx.config.model) : null,
    finished_at: new Date().toISOString(),
  },
};

// ============================================================================
// Mira | Node: "Evaluate Output"   (Code node, Run Once for Each Item)
// Metrics implementation inside the workflow (see docs/04-metrics.md):
//   ONLINE (every request): id_grounding, unknown_ids, footer_compliance,
//                           tokens, cost_usd, latency_ms
//   OFFLINE (baseline / edge-case runs): ground-truth checks -> pass,
//                           check_rate, route_correct
// Results are sent to Langfuse as scores by the next node.
// ============================================================================
// ============================================================================
// Mira | Check engine (JavaScript).  Same rules as eval/checks.py — keep in sync.
// Used inside the n8n "Evaluate Output" node and by tests/check_parity.js.
//
// A check is { id, type, required (default true), ... }:
//   regex            { pattern, flags? }   output must match
//   not_regex        { pattern, flags? }   output must NOT match
//   route            { value: "plan" | ["clarify","status"] }
//   ids_grounded     {}                    every T### / R## in the output exists in the data
//                                          (IDs the user typed in the request are exempt)
//   forbid_ids       { ids: [...] }        none of these IDs may appear
//   percents_allowed { allowed: ["15","10"] } every N% in the output is in the list
//   min_distinct     { pattern, min }      at least `min` distinct matches of pattern
// ============================================================================
function runChecks(output, route, chatInput, checks, dataIds) {
  const text = String(output || '');
  const userText = String(chatInput || '');
  const known = new Set([...(dataIds.tasks || []), ...(dataIds.risks || [])]);
  const userIds = new Set(userText.match(/\b(T\d{3}|R\d{2})\b/g) || []);
  const mentioned = [...new Set(text.match(/\b(T\d{3}|R\d{2})\b/g) || [])];
  const unknownIds = mentioned.filter(id => !known.has(id) && !userIds.has(id));
  const rx = (p, f) => new RegExp(p, (f || 'i').replace(/[^gimsuy]/g, ''));

  const results = (checks || []).map(c => {
    let pass = false, detail = '';
    switch (c.type) {
      case 'regex': pass = rx(c.pattern, c.flags).test(text); break;
      case 'not_regex': { const m = text.match(rx(c.pattern, c.flags)); pass = !m; if (m) detail = `found: ${m[0].slice(0, 60)}`; break; }
      case 'route': { const allowed = [].concat(c.value); pass = allowed.includes(route); detail = `route=${route}`; break; }
      case 'ids_grounded': pass = unknownIds.length === 0; if (!pass) detail = `unknown: ${unknownIds.join(',')}`; break;
      case 'forbid_ids': { const hit = (c.ids || []).filter(id => new RegExp(`\\b${id}\\b`).test(text)); pass = hit.length === 0; if (hit.length) detail = `found: ${hit.join(',')}`; break; }
      case 'percents_allowed': {
        const found = [...new Set((text.match(/\b\d+(?:\.\d+)?\s?%/g) || []).map(s => s.replace(/\s|%/g, '')))];
        const bad = found.filter(n => !(c.allowed || []).includes(n));
        pass = bad.length === 0; if (bad.length) detail = `unexpected: ${bad.map(b => b + '%').join(',')}`; break;
      }
      case 'min_distinct': {
        const found = new Set(text.match(rx(c.pattern, (c.flags || '') + 'g')) || []);
        pass = found.size >= (c.min || 1); detail = `distinct=${found.size}`; break;
      }
      default: detail = `unknown check type ${c.type}`;
    }
    return { id: c.id, type: c.type, required: c.required !== false, pass, detail, label: c.label || '' };
  });

  const req = results.filter(r => r.required);
  return {
    results,
    pass: req.length ? req.every(r => r.pass) : null,
    required_passed: req.filter(r => r.pass).length,
    required_total: req.length,
    check_rate: results.length ? results.filter(r => r.pass).length / results.length : null,
    mentioned_ids: mentioned,
    unknown_ids: unknownIds,
    id_grounding: mentioned.length ? (mentioned.length - unknownIds.length) / mentioned.length : 1,
  };
}


const j = $json;
const ev = runChecks(j.output, j.route, j.chatInput, j.checks, j.data_ids);

const u1 = j.router_usage || {}, u2 = j.specialist_usage || {};
const tokens_in = (u1.prompt_tokens || 0) + (u2.prompt_tokens || 0);
const tokens_out = (u1.completion_tokens || 0) + (u2.completion_tokens || 0);
const cost_usd = (tokens_in * j.config.price_per_1m_input_usd + tokens_out * j.config.price_per_1m_output_usd) / 1e6;
const latency_ms = new Date(j.finished_at) - new Date(j.started_at);

const route_correct = j.expected_route ? [].concat(j.expected_route).includes(j.route) : null;

return {
  json: {
    ...j,
    metrics: {
      id_grounding: ev.id_grounding,
      unknown_ids: ev.unknown_ids,
      footer_compliance: j.route === 'clarify' ? null : (j.footer_added ? 0 : 1),
      tokens_in, tokens_out, cost_usd: Number(cost_usd.toFixed(6)), latency_ms,
      route_correct,
      pass: ev.pass,
      required_passed: ev.required_passed,
      required_total: ev.required_total,
      check_rate: ev.check_rate,
    },
    check_results: ev.results,
  },
};

// ============================================================================
// Mira | Node: "Build Langfuse Trace"   (Code node, Run Once for Each Item)
// Langfuse v4 (Cloud cutover 2026-11-16): traces and generations go to the
// OpenTelemetry endpoint; scores stay on /api/public/ingestion (score-create
// events remain supported after the cutover).
//   langfuse_otel   -> POST {host}/api/public/otel/v1/traces   (OTLP/HTTP JSON)
//       root span   "mira-request"  (input, output, route, test id, prompt version)
//       generation  "agent:router"  (model, tokens, cost, latency)
//       generation  "agent:<route>" (model, tokens, cost, latency)  [not for clarify]
//   langfuse_scores -> POST {host}/api/public/ingestion          (score-create only)
//       id_grounding, footer_compliance, cost_usd, latency_ms,
//       and for graded runs: baseline_pass, check_rate, route_correct
// ============================================================================
const j = $json, m = j.metrics;
const hex = n => Array.from({ length: n }, () => (Math.random() * 16 | 0).toString(16)).join('');
const uid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
  const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16); });
const nanos = iso => (BigInt(Date.parse(iso)) * 1000000n).toString();
const price = { in: j.config.price_per_1m_input_usd, out: j.config.price_per_1m_output_usd };
const traceId = j.trace_id;              // 32 hex chars (OTel trace id = Langfuse trace id)
const rootId = hex(16);

// ---- OTLP attribute helpers ----
const str = (key, v) => ({ key, value: { stringValue: typeof v === 'string' ? v : JSON.stringify(v) } });
const arr = (key, vs) => ({ key, value: { arrayValue: { values: vs.map(v => ({ stringValue: String(v) })) } } });
const tags = ['mira', `route:${j.route}`, `prompt:${j.prompt_version}`, j.mode];
if (j.test_id) tags.push(`test:${j.test_id}`);
if (m.pass === true) tags.push('eval:pass');
if (m.pass === false) tags.push('eval:fail');
// Trace-level attributes are copied to every span (Langfuse v4 requirement for filtering).
const traceAttrs = [
  str('langfuse.trace.name', j.test_id ? `mira-eval ${j.test_id}` : 'mira-request'),
  str('langfuse.session.id', String(j.sessionId)),
  arr('langfuse.trace.tags', tags),
  str('langfuse.version', String(j.prompt_version)),
  str('langfuse.trace.metadata.route', String(j.route)),
  str('langfuse.trace.metadata.test_id', String(j.test_id || '')),
  str('langfuse.trace.metadata.reporting_date', String(j.facts.reporting_date)),
];
const usage = u => u ? { input: u.prompt_tokens || 0, output: u.completion_tokens || 0, total: u.total_tokens || 0 } : null;
const cost = u => u ? { input: (u.prompt_tokens || 0) * price.in / 1e6, output: (u.completion_tokens || 0) * price.out / 1e6,
  total: ((u.prompt_tokens || 0) * price.in + (u.completion_tokens || 0) * price.out) / 1e6 } : null;
const span = ({ name, spanId, parent, start, end, attrs }) => ({
  traceId, spanId, ...(parent ? { parentSpanId: parent } : {}), name, kind: 1,
  startTimeUnixNano: nanos(start), endTimeUnixNano: nanos(end), attributes: [...traceAttrs, ...attrs], status: { code: 1 },
});
const generation = (name, model, u, input, output, start, end, extra = []) => span({
  name, spanId: hex(16), parent: rootId, start, end,
  attrs: [str('langfuse.observation.type', 'generation'), str('langfuse.observation.model.name', String(model || j.config.model)),
    str('langfuse.observation.input', input), str('langfuse.observation.output', output),
    ...(u ? [str('langfuse.observation.usage_details', usage(u)), str('langfuse.observation.cost_details', cost(u))] : []),
    str('langfuse.observation.metadata.prompt_version', String(j.prompt_version)), ...extra],
});

const spans = [
  span({ name: 'mira-request', spanId: rootId, start: j.started_at, end: j.finished_at,
    attrs: [str('langfuse.observation.type', 'agent'), str('langfuse.observation.input', j.chatInput), str('langfuse.observation.output', j.output),
      str('langfuse.observation.metadata.agent', String(j.agent)), str('langfuse.observation.metadata.router_reason', String(j.router_reason || '')),
      str('langfuse.observation.metadata.check_results', j.check_results || [])] }),
  generation('agent:router', j.router_model, j.router_usage, j.chatInput,
    { route: j.route, reason: j.router_reason, reply: j.router_reply }, j.started_at, j.router_done_at),
];
if (j.route !== 'clarify') {
  spans.push(generation(`agent:${j.route}`, j.specialist_model, j.specialist_usage, j.chatInput, j.output, j.router_done_at, j.finished_at,
    [str('langfuse.observation.metadata.footer_added_by_formatter', String(j.footer_added))]));
}
const langfuse_otel = { resourceSpans: [{
  resource: { attributes: [str('service.name', 'mira-n8n')] },
  scopeSpans: [{ scope: { name: 'mira-n8n-workflow', version: String(j.prompt_version) }, spans }],
}] };

// ---- scores (legacy batch endpoint, score-create only — supported after the v4 cutover) ----
const now = new Date().toISOString();
const score = (name, value, comment) => (value === null || value === undefined) ? null : {
  id: uid(), timestamp: now, type: 'score-create',
  body: { id: uid(), traceId, name, value: Number(value), dataType: 'NUMERIC', ...(comment ? { comment } : {}) } };
const langfuse_scores = { batch: [
  score('id_grounding', m.id_grounding, m.unknown_ids.length ? `unknown IDs: ${m.unknown_ids.join(', ')}` : 'all IDs exist in project data'),
  score('footer_compliance', m.footer_compliance),
  score('cost_usd', m.cost_usd),
  score('latency_ms', m.latency_ms),
  score('baseline_pass', m.pass === null ? null : (m.pass ? 1 : 0), j.test_id ? `${j.test_id}: ${m.required_passed}/${m.required_total} required checks` : undefined),
  score('check_rate', m.check_rate),
  score('route_correct', m.route_correct === null ? null : (m.route_correct ? 1 : 0), j.expected_route ? `expected ${[].concat(j.expected_route).join('|')}, got ${j.route}` : undefined),
].filter(Boolean) };

return { json: { ...j, langfuse_otel, langfuse_scores } };

// ============================================================================
// Mira | Node: "Chat Response"   (Code node, Run Once for Each Item)
// Last node: the Chat Trigger shows `output` to the user. Test runs also get a
// compact result row (test id, route, pass, cost) for the execution log.
// ============================================================================
const r = $('Build Langfuse Trace').item.json;
const ok = x => !!x && !x.error && !(Array.isArray(x.errors) && x.errors.length) && !(x.partialSuccess && x.partialSuccess.rejectedSpans);
const traces_ok = ok($('Langfuse: Traces (OTel)').item.json);
const scores_ok = ok($json);
return {
  json: {
    output: r.output,
    route: r.route,
    agent: r.agent,
    test_id: r.test_id || 'none (free-form chat)',
    graded: r.test_id ? `graded against ground-truth test ${r.test_id}` : 'not graded: message does not match a ground-truth test input (online metrics still computed)',
    pass: r.metrics.pass,
    route_correct: r.metrics.route_correct,
    check_rate: r.metrics.check_rate,
    failed_checks: (r.check_results || []).filter(c => !c.pass).map(c => `${c.id}${c.required ? '' : ' (optional)'}: ${c.detail || c.label}`),
    id_grounding: r.metrics.id_grounding,
    tokens_in: r.metrics.tokens_in,
    tokens_out: r.metrics.tokens_out,
    cost_usd: r.metrics.cost_usd,
    latency_ms: r.metrics.latency_ms,
    prompt_version: r.prompt_version,
    trace_id: r.trace_id,
    langfuse_logged: traces_ok && scores_ok,
    langfuse_detail: `traces ${traces_ok ? 'ok' : 'FAILED'} (OTel), scores ${scores_ok ? 'ok' : 'FAILED'} (ingestion)`,
  },
};
